const { withAppBuildGradle } = require("expo/config-plugins");

// Generated by Expo prebuild; credentials are read by Gradle, never embedded in config.
module.exports = (config) =>
  withAppBuildGradle(config, (mod) => {
    if (mod.modResults.language !== "groovy")
      throw new Error("Expected a Groovy Android build");
    if (
      mod.modResults.contents.includes("// Disposabl production APK signing.")
    )
      return mod;
    mod.modResults.contents += `
// Disposabl production APK signing. Preview APKs retain Expo's debug signing.
if (System.getenv("DISPOSABL_ANDROID_CHANNEL") == "production") {
    android {
        signingConfigs {
            disposablRelease {
                storeFile file(System.getenv("ANDROID_KEYSTORE_PATH"))
                storePassword System.getenv("ANDROID_KEYSTORE_PASSWORD")
                keyAlias System.getenv("ANDROID_KEY_ALIAS")
                keyPassword System.getenv("ANDROID_KEY_PASSWORD")
            }
        }
        buildTypes.release.signingConfig = signingConfigs.disposablRelease
    }
}
`;
    return mod;
  });
